ALTER TABLE public.fixed_assets ADD COLUMN IF NOT EXISTS source_invoice_line_id uuid REFERENCES public.invoice_line_items(id);
CREATE UNIQUE INDEX IF NOT EXISTS fixed_asset_invoice_line_once ON public.fixed_assets(tenant_id,source_invoice_line_id) WHERE source_invoice_line_id IS NOT NULL;
CREATE OR REPLACE FUNCTION public.finance_invoice_asset_source(t uuid, ident uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE l invoice_line_items;i invoices;v jsonb;BEGIN
IF NOT finance_schedule_manager(t) THEN RAISE EXCEPTION 'Owner or admin required';END IF;
SELECT * INTO l FROM invoice_line_items WHERE tenant_id=t AND id=ident FOR UPDATE;SELECT * INTO i FROM invoices WHERE tenant_id=t AND id=l.invoice_id FOR UPDATE;IF i.id IS NULL THEN RAISE EXCEPTION 'Invoice line unavailable';END IF;
SELECT jsonb_build_object('line',to_jsonb(l),'invoice',to_jsonb(i),'account',coalesce(pm.default_coa_account_id,am.account_id),'postings',(SELECT coalesce(jsonb_agg(jsonb_build_object('entry',to_jsonb(e),'lines',(SELECT jsonb_agg(to_jsonb(jl) ORDER BY jl.id) FROM journal_lines jl WHERE jl.entry_id=e.id AND jl.tenant_id=t)) ORDER BY e.id),'[]') FROM journal_entries e WHERE e.tenant_id=t AND e.source_type='invoice' AND e.source_id=i.id::text AND e.status='posted')) INTO v FROM (SELECT 1) x LEFT JOIN product_master pm ON pm.id=l.product_master_id AND pm.tenant_id=t LEFT JOIN account_mapping_rules am ON am.tenant_id=t AND am.rule_type='procurement_category' AND am.match_key=coalesce(pm.financial_treatment,'')||'__'||coalesce(pm.level1_category,'') LIMIT 1;RETURN v;END $$;
REVOKE ALL ON FUNCTION public.finance_invoice_asset_source(uuid,uuid) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.finance_invoice_asset_source(uuid,uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.finance_invoice_asset_propose(t uuid,p jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v jsonb;l invoice_line_items;i invoices;asset uuid;d date:=(p->>'date')::date;posted boolean;ident uuid;BEGIN
IF NOT finance_schedule_manager(t) THEN RAISE EXCEPTION 'Owner or admin required';END IF;PERFORM pg_advisory_xact_lock(hashtextextended('schedule:'||t,0));v:=finance_invoice_asset_source(t,(p->>'line')::uuid);l:=jsonb_populate_record(NULL::invoice_line_items,v->'line');i:=jsonb_populate_record(NULL::invoices,v->'invoice');posted:=jsonb_array_length(v->'postings')>0;PERFORM finance_assert_open(t,d);IF NOT posted THEN PERFORM finance_assert_open(t,i.invoice_date);END IF;
IF l.total<=coalesce((SELECT capitalisation_limit FROM finance_schedule_settings WHERE tenant_id=t),5000) OR i.review_status IN('Disputed','Voided') OR i.has_disputes OR i.held_amount>0 OR coalesce((p->>'life_months')::int,0) NOT BETWEEN 1 AND 1200 OR nullif(btrim(p->>'name'),'') IS NULL OR NOT EXISTS(SELECT 1 FROM chart_of_accounts WHERE tenant_id=t AND id=(v->>'account')::uuid AND account_type IN('opex','cogs','other_expense') AND is_active) THEN RAISE EXCEPTION 'Confirm eligible expense line, asset name and life';END IF;
IF EXISTS(SELECT 1 FROM fixed_assets WHERE tenant_id=t AND source_invoice_line_id=l.id) OR EXISTS(SELECT 1 FROM finance_entry_drafts WHERE tenant_id=t AND source_data->>'invoice_asset_line'=l.id::text AND status IN('waiting','approved')) THEN RAISE EXCEPTION 'Asset proposal already exists';END IF;
IF posted AND coalesce((SELECT sum((x->>'debit')::numeric-(x->>'credit')::numeric) FROM jsonb_array_elements(v->'postings') e CROSS JOIN LATERAL jsonb_array_elements(e->'lines') x WHERE x->>'account_id'=v->>'account'),0)<l.total THEN RAISE EXCEPTION 'Posted expense coverage unavailable';END IF;
asset:=finance_schedule_account(t,CASE p->>'category' WHEN 'kitchen_equipment' THEN '1520' WHEN 'furniture_fixtures' THEN '1510' WHEN 'it_equipment' THEN '1530' WHEN 'leasehold_improvements' THEN '1540' ELSE '1500' END,'Fixed Assets','asset');
ident:=finance_schedule_enqueue(t,d,'manual',p->>'name',CASE WHEN posted THEN 'Invoice asset correction; original invoice and journal retained' ELSE 'Invoice asset treatment; source posts only at selected approval' END,'invoice-asset:'||l.id,jsonb_build_array(jsonb_build_object('account_id',asset,'debit',round(l.total,2),'credit',0,'venue',i.venue),jsonb_build_object('account_id',v->>'account','debit',0,'credit',round(l.total,2),'venue',i.venue)),jsonb_build_object('invoice_asset_line',l.id,'fingerprint',md5(v::text),'posted',posted,'name',p->>'name','category',p->>'category','life_months',(p->>'life_months')::int,'in_service_date',d,'invoice',i.id),i.file_url,CASE WHEN posted THEN (v->'postings'->0->'entry'->>'id')::uuid ELSE NULL END);RETURN ident;END $$;
REVOKE ALL ON FUNCTION public.finance_invoice_asset_propose(uuid,jsonb) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.finance_invoice_asset_propose(uuid,jsonb) TO authenticated;
CREATE OR REPLACE FUNCTION public.finance_invoice_asset_account(t uuid,line_id uuid,original uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE q finance_entry_drafts;BEGIN SELECT * INTO q FROM finance_entry_drafts WHERE tenant_id=t AND source_data->>'invoice_asset_line'=line_id::text AND status='waiting' AND id::text=current_setting('finance.invoice_asset_approval',true);IF q.id IS NULL THEN RETURN original;END IF;RETURN (q.lines->0->>'account_id')::uuid;END $$;
REVOKE ALL ON FUNCTION public.finance_invoice_asset_account(uuid,uuid,uuid) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.finance_invoice_asset_account(uuid,uuid,uuid) TO authenticated;
DO $$ DECLARE def text;BEGIN SELECT pg_get_functiondef('public._rebuild_journal_from_operations_impl(uuid,uuid,text)'::regprocedure) INTO def;
IF position('COALESCE(NULLIF(pm.default_coa_account_id::text,'''')::uuid, amr.account_id) AS acct' IN def)=0 THEN RAISE EXCEPTION 'Invoice mapping anchor changed';END IF;
def:=replace(def,'COALESCE(NULLIF(pm.default_coa_account_id::text,'''')::uuid, amr.account_id) AS acct','public.finance_invoice_asset_account(p_tenant_id,li.id,COALESCE(NULLIF(pm.default_coa_account_id::text,'''')::uuid, amr.account_id)) AS acct');
def:=replace(def,'WHERE i.tenant_id = p_tenant_id AND i.review_status=''Approved''','WHERE NOT EXISTS(SELECT 1 FROM public.finance_entry_drafts aq WHERE aq.tenant_id=p_tenant_id AND aq.source_data->>''invoice''=i.id::text AND aq.source_data ? ''invoice_asset_line'' AND aq.status=''waiting'' AND aq.id::text IS DISTINCT FROM current_setting(''finance.invoice_asset_approval'',true)) AND i.tenant_id = p_tenant_id AND i.review_status=''Approved''');EXECUTE def;END $$;
CREATE OR REPLACE FUNCTION public.finance_invoice_asset_approve(t uuid,ident uuid,m date) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE q finance_entry_drafts;v jsonb;l invoice_line_items;i invoices;j uuid;a uuid;accum uuid;expense uuid;cur date;cost numeric;part numeric;total numeric:=0;n int;BEGIN
IF NOT finance_schedule_manager(t) THEN RAISE EXCEPTION 'Owner or admin required';END IF;PERFORM pg_advisory_xact_lock(hashtextextended('schedule:'||t,0));SELECT * INTO q FROM finance_entry_drafts WHERE tenant_id=t AND id=ident AND status='waiting' AND date_trunc('month',entry_date)=date_trunc('month',m) FOR UPDATE;IF q.id IS NULL THEN RAISE EXCEPTION 'Draft changed';END IF;PERFORM finance_assert_open(t,q.entry_date);v:=finance_invoice_asset_source(t,(q.source_data->>'invoice_asset_line')::uuid);IF md5(v::text) IS DISTINCT FROM q.source_data->>'fingerprint' THEN RAISE EXCEPTION 'Invoice source changed; prepare again';END IF;l:=jsonb_populate_record(NULL::invoice_line_items,v->'line');i:=jsonb_populate_record(NULL::invoices,v->'invoice');
IF EXISTS(SELECT 1 FROM fixed_assets WHERE tenant_id=t AND source_invoice_line_id=l.id) THEN RAISE EXCEPTION 'Asset already assigned';END IF;
IF NOT (q.source_data->>'posted')::boolean THEN
PERFORM finance_assert_open(t,i.invoice_date);IF i.review_status<>'Approved' OR i.has_disputes OR i.held_amount>0 THEN RAISE EXCEPTION 'Approve the invoice and resolve delivery first';END IF;
IF NOT EXISTS(SELECT 1 FROM goods_received_notes g WHERE g.invoice_id=i.id AND g.tenant_id=t AND g.status='confirmed' AND g.received_by IS NOT NULL AND EXISTS(SELECT 1 FROM grn_items c WHERE c.grn_id=g.id) AND NOT EXISTS(SELECT 1 FROM invoice_line_items il WHERE il.invoice_id=i.id AND il.tenant_id=t AND NOT EXISTS(SELECT 1 FROM grn_items c WHERE c.grn_id=g.id AND c.invoice_line_item_id=il.id AND c.human_counted_at IS NOT NULL AND c.quantity_received=c.quantity_invoiced))) THEN RAISE EXCEPTION 'Delivery needs a human count';END IF;
PERFORM set_config('finance.invoice_asset_approval',q.id::text,true);PERFORM set_config('bani.accounting.source_type','invoice',true);PERFORM set_config('bani.accounting.source_id',i.id::text,true);PERFORM _rebuild_journal_from_operations_impl(t,auth.uid(),'Selected asset approval');SELECT id INTO j FROM journal_entries WHERE tenant_id=t AND source_type='invoice' AND source_id=i.id::text AND status='posted';IF j IS NULL THEN RAISE EXCEPTION 'Invoice has unresolved accounting mappings';END IF;PERFORM set_config('finance.invoice_asset_approval','',true);PERFORM set_config('bani.accounting.source_type','',true);PERFORM set_config('bani.accounting.source_id','',true);UPDATE finance_entry_drafts SET status='approved',journal_entry_id=j,approved_by=auth.uid(),approved_at=now() WHERE id=q.id;
ELSE
PERFORM set_config('finance.invoice_asset_delegate',q.id::text,true);j:=finance_schedule_approve(t,q.id,m);PERFORM set_config('finance.invoice_asset_delegate','',true);
END IF;
accum:=finance_schedule_account(t,'1550','Accumulated Depreciation','asset');expense:=finance_schedule_account(t,'6900','Depreciation Expense','opex');cost:=round(l.total,2);INSERT INTO fixed_assets(tenant_id,name,category,purchase_date,in_service_date,cost,useful_life_months,venue,supplier_id,source_invoice_line_id,asset_account_id,accumulated_depr_account_id,expense_account_id,amount_remaining,notes,created_by,proposal_draft_id) VALUES(t,q.source_data->>'name',q.source_data->>'category',i.invoice_date,(q.source_data->>'in_service_date')::date,cost,(q.source_data->>'life_months')::int,i.venue,i.supplier_id,l.id,(q.lines->0->>'account_id')::uuid,accum,expense,cost,'Approved invoice asset',auth.uid(),q.id) RETURNING id INTO a;
cur:=date_trunc('month',(q.source_data->>'in_service_date')::date)::date;FOR n IN 1..(q.source_data->>'life_months')::int LOOP part:=CASE WHEN n=(q.source_data->>'life_months')::int THEN cost-total ELSE round(cost/(q.source_data->>'life_months')::int,2) END;INSERT INTO fixed_asset_depreciation_schedule(tenant_id,asset_id,period_year,period_month,scheduled_amount,status) VALUES(t,a,extract(year FROM cur),extract(month FROM cur),part,'pending');total:=total+part;cur:=(cur+interval '1 month')::date;END LOOP;RETURN j;END $$;
REVOKE ALL ON FUNCTION public.finance_invoice_asset_approve(uuid,uuid,date) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.finance_invoice_asset_approve(uuid,uuid,date) TO authenticated;
DO $$ DECLARE def text;anchor text:='PERFORM finance_assert_open(t,q.entry_date);';BEGIN SELECT pg_get_functiondef('public.finance_schedule_approve(uuid,uuid,date)'::regprocedure) INTO def;IF position(anchor IN def)=0 THEN RAISE EXCEPTION 'Approval anchor changed';END IF;def:=replace(def,anchor,anchor||'IF q.source_data ? ''invoice_asset_line'' AND current_setting(''finance.invoice_asset_delegate'',true) IS DISTINCT FROM q.id::text THEN RETURN public.finance_invoice_asset_approve(t,q.id,m);END IF;');EXECUTE def;END $$;